function permsFor(member, isAdmin) {
  // Admin bypasses the whole system — always full access.
  if (isAdmin) {
    const all = {};
    PERMISSIONS.forEach((p) => {
      all[p.id] = true;
    });
    return all;
  }
  return { ...DEFAULT_MEMBER_PERMISSIONS, ...((member && member.permissions) || {}) };
}

