const STORAGE_KEY = "senior_hub_v2";

function defaultCountdowns(kidKey) {
  return [{ id: "graduation", label: "Graduation", date: THEMES[kidKey].graduation.slice(0, 10), locked: true }];
}

function loadStore() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (!parsed.settings) parsed.settings = { phoneNumbers: [] };
      if (parsed.settings.accessCode === undefined) parsed.settings.accessCode = "";
      if (parsed.settings.deviceUnlocked === undefined) parsed.settings.deviceUnlocked = false;
      if (parsed.settings.syncUrl === undefined) parsed.settings.syncUrl = APP_CONFIG.syncUrl;
      if (parsed.settings.googleClientId === undefined) parsed.settings.googleClientId = APP_CONFIG.googleClientId;
      if (!parsed.settings.members) parsed.settings.members = [];
      ["tyler", "gracie"].forEach((k) => {
        if (parsed[k] && parsed[k].headerPreset === undefined) parsed[k].headerPreset = "solid";
        if (parsed[k] && parsed[k].headerBg === undefined) parsed[k].headerBg = null;
        if (parsed[k] && !parsed[k].countdowns) parsed[k].countdowns = defaultCountdowns(k);
        if (parsed[k] && !parsed[k].activeCountdown) parsed[k].activeCountdown = "graduation";
        if (parsed[k] && !parsed[k].budget) parsed[k].budget = { categories: DEFAULT_BUDGET_CATEGORIES.map((c) => ({ ...c })) };
        if (parsed[k] && parsed[k].profilePic === undefined) parsed[k].profilePic = null;
        if (parsed[k] && parsed[k].photos) {
          parsed[k].photos = parsed[k].photos.map((p) => (p.tags ? p : { ...p, tags: [] }));
        }
      });
      return parsed;
    }
  } catch (e) {}
  const initial = {
    settings: {
      phoneNumbers: [],
      accessCode: "",
      deviceUnlocked: false,
      syncUrl: APP_CONFIG.syncUrl,
      googleClientId: APP_CONFIG.googleClientId,
      members: [],
    },
  };
  ["tyler", "gracie"].forEach((k) => {
    initial[k] = {
      events: SEED_EVENTS[k],
      milestones: SEED_MILESTONES.map((m) => ({ ...m })),
      photos: [],
      party: {},
      headerBg: null,
      headerPreset: "solid",
      countdowns: defaultCountdowns(k),
      activeCountdown: "graduation",
      budget: { categories: DEFAULT_BUDGET_CATEGORIES.map((c) => ({ ...c })) },
      profilePic: null,
    };
  });
  return initial;
}

function saveStore(store) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(store));
  } catch (e) {}
}

/* ---------- Google auth session (sessionStorage only — clears when the
   browser tab/session ends, so signing in doesn't linger forever) ---------- */
const AUTH_SESSION_KEY = "senior_hub_google_auth";

/* ---------- Member identity (who's using this device) ----------
   Stored in localStorage so a family member only introduces themselves
   once per device. The actual approve/deny decision lives in the shared
   synced members list, so approving on your phone unlocks their device. */
const MEMBER_KEY = "senior_hub_member_id";

function loadMemberId() {
  try {
    return localStorage.getItem(MEMBER_KEY) || null;
  } catch (e) {
    return null;
  }
}

function saveMemberId(id) {
  try {
    localStorage.setItem(MEMBER_KEY, id);
  } catch (e) {}
}

function clearMemberId() {
  try {
    localStorage.removeItem(MEMBER_KEY);
  } catch (e) {}
}


function loadGoogleAuthSession() {
  try {
    const raw = sessionStorage.getItem(AUTH_SESSION_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed.exp || parsed.exp * 1000 < Date.now()) return null; // expired
    return parsed;
  } catch (e) {
    return null;
  }
}

function saveGoogleAuthSession(auth) {
  try {
    sessionStorage.setItem(AUTH_SESSION_KEY, JSON.stringify(auth));
  } catch (e) {}
}

function clearGoogleAuthSession() {
  try {
    sessionStorage.removeItem(AUTH_SESSION_KEY);
  } catch (e) {}
}

/* ---------- shared sync (Google Drive via Apps Script Web App) ----------
   syncUrl points to a small Apps Script Web App that reads/writes a single
   JSON file in the family's Google Drive. See google-apps-script/Code.gs
   and the README for setup. This is whole-store, last-write-wins sync —
   fine for casual family use, not built for simultaneous multi-editor
   conflict resolution.

   If Google Sign-In is configured, every request carries the signed-in
   user's Google ID token, and the Apps Script itself verifies it (and
   checks the email against its allow-list) before returning or saving
   anything — the gate isn't just cosmetic on the front end. */
async function fetchRemoteStore(url, token) {
  const sep = url.includes("?") ? "&" : "?";
  const fetchUrl = token ? `${url}${sep}token=${encodeURIComponent(token)}` : url;
  const res = await fetch(fetchUrl, { method: "GET", cache: "no-store" });
  if (!res.ok) throw new Error("Sync fetch failed: " + res.status);
  const data = await res.json();
  if (data && data.ok === false) {
    const err = new Error(data.error || "Unauthorized");
    err.unauthorized = data.error === "Unauthorized";
    throw err;
  }
  return data;
}

async function pushRemoteStore(url, store, token) {
  // text/plain avoids a CORS preflight against the Apps Script endpoint;
  // the script itself parses the body as JSON.
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "text/plain;charset=utf-8" },
    body: JSON.stringify({ token: token || null, data: store }),
  });
  if (!res.ok) throw new Error("Sync push failed: " + res.status);
  const data = await res.json();
  if (data && data.ok === false) {
    const err = new Error(data.error || "Unauthorized");
    err.unauthorized = data.error === "Unauthorized";
    throw err;
  }
  return data;
}

/* Decodes (does NOT verify) a JWT payload — fine for reading display info
   like name/email/picture client-side. Verification of the signature and
   allow-list happens server-side in the Apps Script for every sync call. */
function parseJwt(token) {
  try {
    const base64 = token.split(".")[1].replace(/-/g, "+").replace(/_/g, "/");
    const json = decodeURIComponent(
      atob(base64)
        .split("")
        .map((c) => "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2))
        .join("")
    );
    return JSON.parse(json);
  } catch (e) {
    return null;
  }
}

/* ---------- utility ---------- */
function daysUntil(iso) {
  const now = new Date();
  const target = new Date(iso);
  const diff = Math.ceil((target - now) / (1000 * 60 * 60 * 24));
  return diff;
}

function fmtDate(iso) {
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function fmtTime(t) {
  if (!t) return "";
  const [h, m] = t.split(":").map(Number);
  const period = h >= 12 ? "PM" : "AM";
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(m).padStart(2, "0")} ${period}`;
}

function monthLabel(iso) {
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("en-US", { month: "long", year: "numeric" });
}

/* Reads a File, downsizes it on a canvas, and returns a compressed JPEG data URL.
   Keeps photos small enough to store reliably and reduces broken-image odds. */
function fileToCompressedDataUrl(file, maxDim, quality) {
  maxDim = maxDim || 1600;
  quality = quality || 0.82;
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Could not read that file."));
    reader.onload = () => {
      const img = new window.Image();
      img.onerror = () => reject(new Error("Could not load that image."));
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height = Math.round((height * maxDim) / width);
            width = maxDim;
          } else {
            width = Math.round((width * maxDim) / height);
            height = maxDim;
          }
        }
        try {
          const canvas = document.createElement("canvas");
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL("image/jpeg", quality));
        } catch (e) {
          resolve(reader.result);
        }
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

