    if (!file) return;
    setError("");
    fileToCompressedDataUrl(file, 1600, 0.85)
      .then((dataUrl) => updateKid((d) => ({ ...d, headerBg: dataUrl })))
      .catch(() => setError("Couldn't load that photo — try a different file."));
