/* ============================================================
   PARTY PLANNER TAB
   ============================================================ */
function PartyTab({ theme, data, updateKid, familyView, perms }) {
  const canSeeBudget = !perms || perms.viewBudget;
  const [view, setView] = useState("checklist"); // "checklist" | "budget"

  function toggle(key) {
    if (familyView) return;
    updateKid((d) => ({ ...d, party: { ...d.party, [key]: !d.party[key] } }));
  }

  return (
    <div style={{ padding: 20, display: "flex", flexDirection: "column", gap: 16 }}>
      {canSeeBudget && (
        <div style={{ display: "flex", background: theme.border, borderRadius: 9, padding: 3 }}>
          {["checklist", "budget"].map((v) => (
            <button
              key={v}
              onClick={() => setView(v)}
              style={{
                flex: 1,
                border: "none",
                borderRadius: 7,
                padding: "8px 0",
                fontSize: 13,
                fontWeight: 800,
                cursor: "pointer",
                background: view === v ? theme.card : "transparent",
                color: view === v ? theme.text : theme.subtext,
                boxShadow: view === v ? "0 1px 2px rgba(0,0,0,0.08)" : "none",
                textTransform: "capitalize",
              }}
            >
              {v === "checklist" ? "✅ Checklist" : "💰 Budget"}
            </button>
          ))}
        </div>
      )}

      {view === "checklist" || !canSeeBudget ? (
        <>
          {PARTY_CATEGORIES.map((cat) => {
            const doneCount = cat.items.filter((it) => data.party[`${cat.id}:${it}`]).length;
            return (
              <SectionCard
                key={cat.id}
                theme={theme}
                title={cat.label}
                right={
                  <span style={{ fontSize: 12, fontWeight: 700, color: theme.subtext }}>
                    {doneCount}/{cat.items.length}
                  </span>
                }
              >
                {cat.items.map((item, i) => {
                  const key = `${cat.id}:${item}`;
                  const checked = !!data.party[key];
                  return (
                    <label
                      key={key}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 10,
                        padding: "8px 0",
                        cursor: familyView ? "default" : "pointer",
                        borderBottom: i < cat.items.length - 1 ? `1px solid ${theme.border}` : "none",
                      }}
                    >
                      <input
                        type="checkbox"
                        checked={checked}
                        disabled={familyView}
                        onChange={() => toggle(key)}
                        style={{ width: 18, height: 18, accentColor: theme.primary }}
                      />
                      <span
                        style={{
                          fontSize: 14,
                          fontWeight: 600,
                          textDecoration: checked ? "line-through" : "none",
                          color: checked ? theme.subtext : theme.text,
                        }}
                      >
                        {item}
                      </span>
                    </label>
                  );
                })}
              </SectionCard>
            );
          })}
        </>
      ) : (
        <BudgetView theme={theme} data={data} updateKid={updateKid} familyView={familyView} />
      )}
    </div>
  );
}

function BudgetView({ theme, data, updateKid, familyView }) {
  const categories = (data.budget && data.budget.categories) || DEFAULT_BUDGET_CATEGORIES;
  const totalBudgeted = categories.reduce((s, c) => s + (Number(c.budgeted) || 0), 0);
  const totalSpent = categories.reduce((s, c) => s + (Number(c.spent) || 0), 0);
  const pct = totalBudgeted > 0 ? Math.min(100, Math.round((totalSpent / totalBudgeted) * 100)) : 0;
  const overBudget = totalSpent > totalBudgeted && totalBudgeted > 0;

  function updateCategory(id, field, value) {
    updateKid((d) => ({
      ...d,
      budget: {
        ...d.budget,
        categories: (d.budget.categories || categories).map((c) =>
          c.id === id ? { ...c, [field]: value } : c
        ),
      },
    }));
  }

  return (
    <>
      <SectionCard theme={theme} title="Total">
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
          <div>
            <div style={{ fontSize: 22, fontWeight: 900, color: overBudget ? "#B33A3A" : theme.primary }}>
              ${totalSpent.toLocaleString()}
            </div>
            <div style={{ fontSize: 11.5, color: theme.subtext, fontWeight: 700 }}>spent</div>
          </div>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontSize: 22, fontWeight: 900, color: theme.text }}>
              ${totalBudgeted.toLocaleString()}
            </div>
            <div style={{ fontSize: 11.5, color: theme.subtext, fontWeight: 700 }}>budgeted</div>
          </div>
        </div>
        <div style={{ background: theme.border, borderRadius: 20, height: 10, overflow: "hidden" }}>
          <div
            style={{
              width: `${pct}%`,
              height: "100%",
              background: overBudget ? "#B33A3A" : theme.primary,
              borderRadius: 20,
              transition: "width 0.3s ease",
            }}
          />
        </div>
        {overBudget && (
          <div style={{ fontSize: 12, color: "#B33A3A", fontWeight: 700, marginTop: 8 }}>
            ⚠ ${(totalSpent - totalBudgeted).toLocaleString()} over budget
          </div>
        )}
      </SectionCard>

      {categories.map((c) => (
        <SectionCard key={c.id} theme={theme} title={c.label}>
          <div style={{ display: "flex", gap: 12 }}>
            <div style={{ flex: 1 }}>
              <FieldLabel theme={theme}>Budgeted ($)</FieldLabel>
              <input
                type="number"
                min="0"
                value={c.budgeted}
                disabled={familyView}
                onChange={(e) => updateCategory(c.id, "budgeted", Number(e.target.value))}
                style={inputStyle(theme)}
              />
            </div>
            <div style={{ flex: 1 }}>
              <FieldLabel theme={theme}>Spent ($)</FieldLabel>
              <input
                type="number"
                min="0"
                value={c.spent}
                disabled={familyView}
                onChange={(e) => updateCategory(c.id, "spent", Number(e.target.value))}
                style={inputStyle(theme)}
              />
            </div>
          </div>
        </SectionCard>
      ))}
    </>
  );
}

/* ============================================================
   SUBMIT PHOTO TAB
   ============================================================ */
function SubmitTab({ theme, data, updateKid }) {
  const [caption, setCaption] = useState("");
  const [preview, setPreview] = useState(null);
  const [submitted, setSubmitted] = useState(false);
  const [tags, setTags] = useState([]);
  const [fileError, setFileError] = useState("");
  const fileRef = useRef(null);

  function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    setFileError("");
    fileToCompressedDataUrl(file)
      .then((dataUrl) => setPreview(dataUrl))
      .catch(() => setFileError("Couldn't load that photo — try a different file."));
  }

  function toggleTag(tagId) {
    setTags((prev) => (prev.includes(tagId) ? prev.filter((t) => t !== tagId) : [...prev, tagId]));
  }

  function submit() {
    if (!preview) return;
    updateKid((d) => ({
      ...d,
      photos: [
        ...d.photos,
        { id: Date.now().toString(), url: preview, caption, approved: false, tags },
      ],
    }));
    setPreview(null);
    setCaption("");
    setTags([]);
    if (fileRef.current) fileRef.current.value = "";
    setSubmitted(true);
    setTimeout(() => setSubmitted(false), 2500);
  }

  return (
    <div style={{ padding: 20 }}>
      <SectionCard theme={theme} title={`Share a photo — ${theme.name}'s senior year`}>
        <div style={{ fontSize: 13.5, color: theme.subtext, marginBottom: 14, lineHeight: 1.5 }}>
          Friends and family — thank you for contributing! Photos go through a quick review before
          they appear in the gallery and party slideshow.
        </div>

        <div
          onClick={() => fileRef.current && fileRef.current.click()}
          style={{
            border: `2px dashed ${theme.border}`,
            borderRadius: 12,
            padding: preview ? 0 : 32,
            textAlign: "center",
            cursor: "pointer",
            overflow: "hidden",
            marginBottom: 14,
          }}
        >
          {preview ? (
            <img src={preview} alt="" style={{ width: "100%", maxHeight: 260, objectFit: "cover", display: "block" }} />
          ) : (
            <>
              <div style={{ fontSize: 28, marginBottom: 6 }}>📷</div>
              <div style={{ fontWeight: 700, fontSize: 14 }}>Tap to choose a photo</div>
            </>
          )}
        </div>
        <input ref={fileRef} type="file" accept="image/*" onChange={handleFile} style={{ display: "none" }} />
        {fileError && (
          <div style={{ fontSize: 12.5, color: "#B33A3A", fontWeight: 600, marginBottom: 12 }}>{fileError}</div>
        )}

        <input
          type="text"
          placeholder="Add a caption (optional)"
          value={caption}
          onChange={(e) => setCaption(e.target.value)}
          style={{
            width: "100%",
            boxSizing: "border-box",
            border: `1.5px solid ${theme.border}`,
            borderRadius: 8,
            padding: "10px 12px",
            fontSize: 14,
            marginBottom: 14,
            fontFamily: "inherit",
          }}
        />

        <div style={{ fontSize: 12, fontWeight: 700, color: theme.subtext, marginBottom: 8 }}>
          Tag this photo (optional)
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 18 }}>
          {PHOTO_TAGS.map((tag) => {
            const active = tags.includes(tag.id);
            return (
              <button
                key={tag.id}
                onClick={() => toggleTag(tag.id)}
                style={{
                  border: `1.5px solid ${active ? theme.primary : theme.border}`,
                  background: active ? theme.primary : "transparent",
                  color: active ? theme.onPrimary : theme.text,
                  borderRadius: 20,
                  padding: "6px 14px",
                  fontSize: 12.5,
                  fontWeight: 700,
                  cursor: "pointer",
                }}
              >
                {tag.label}
              </button>
            );
          })}
        </div>

        <button
          onClick={submit}
          disabled={!preview}
          style={{
            width: "100%",
            background: preview ? theme.primary : theme.border,
            color: preview ? theme.onPrimary : theme.subtext,
            border: "none",
            borderRadius: 9,
            padding: "12px 0",
            fontWeight: 800,
            fontSize: 14.5,
            cursor: preview ? "pointer" : "not-allowed",
          }}
        >
          {submitted ? "Submitted! Thank you 🎉" : "Submit photo"}
        </button>
      </SectionCard>
    </div>
  );
}

