/* ---------- Admin: one member's row, expandable into a permission editor ---------- */
function MemberRow({ member, onRemove, onSetPermissions }) {
  const [open, setOpen] = useState(false);
  const [confirmRemove, setConfirmRemove] = useState(false);
  const isAdminRow = member.role === "admin";
  const current = { ...DEFAULT_MEMBER_PERMISSIONS, ...(member.permissions || {}) };
  const grantedCount = PERMISSIONS.filter((p) => current[p.id]).length;

  function togglePerm(id) {
    onSetPermissions(member.id, { ...current, [id]: !current[id] });
  }

  function applyPreset(key) {
    onSetPermissions(member.id, { ...PERMISSION_PRESETS[key].perms });
  }

  return (
    <div style={{ border: "1px solid #EDEAF3", borderRadius: 9, overflow: "hidden" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "9px 12px", gap: 8 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
          {member.photo ? (
            <img
              src={member.photo}
              alt=""
              style={{ width: 32, height: 32, borderRadius: "50%", objectFit: "cover", flexShrink: 0 }}
            />
          ) : (
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: "50%",
                background: "#F1EFF5",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: 14,
                flexShrink: 0,
              }}
            >
              👤
            </div>
          )}
          <div style={{ minWidth: 0 }}>
            <div style={{ fontSize: 13, fontWeight: 700 }}>
              {member.name} {isAdminRow && <span style={{ color: "#4B2E83", fontSize: 11 }}>★ admin</span>}
            </div>
            <div
              style={{
                fontSize: 11.5,
                color: "#8A8494",
                overflow: "hidden",
                textOverflow: "ellipsis",
                whiteSpace: "nowrap",
              }}
            >
              {isAdminRow
                ? "Full access"
                : `${grantedCount} of ${PERMISSIONS.length} permissions`}
            </div>
          </div>
        </div>
        {!isAdminRow && (
          <button
            onClick={() => setOpen(!open)}
            style={{
              background: "transparent",
              border: "1px solid #E0DCE8",
              borderRadius: 6,
              padding: "5px 10px",
              fontSize: 11,
              fontWeight: 700,
              cursor: "pointer",
              color: "#4B2E83",
              flexShrink: 0,
            }}
          >
            {open ? "Done" : "Manage"}
          </button>
        )}
      </div>

      {open && !isAdminRow && (
        <div style={{ borderTop: "1px solid #EDEAF3", padding: 12, background: "#FBFAFD" }}>
          <div style={{ fontSize: 11, fontWeight: 800, color: "#8A8494", marginBottom: 8 }}>
            QUICK SET
          </div>
          <div style={{ display: "flex", gap: 6, marginBottom: 14, flexWrap: "wrap" }}>
            {Object.entries(PERMISSION_PRESETS).map(([key, preset]) => (
              <button
                key={key}
                onClick={() => applyPreset(key)}
                title={preset.hint}
                style={{
                  border: "1.5px solid #D9D2EC",
                  background: "#fff",
                  color: "#4B2E83",
                  borderRadius: 16,
                  padding: "5px 12px",
                  fontSize: 11.5,
                  fontWeight: 700,
                  cursor: "pointer",
                }}
              >
                {preset.label}
              </button>
            ))}
          </div>

          <div style={{ fontSize: 11, fontWeight: 800, color: "#8A8494", marginBottom: 8 }}>
            PERMISSIONS
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 2, marginBottom: 14 }}>
            {PERMISSIONS.map((p) => (
              <label
                key={p.id}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: 9,
                  padding: "7px 0",
                  cursor: "pointer",
                }}
              >
                <input
                  type="checkbox"
                  checked={!!current[p.id]}
                  onChange={() => togglePerm(p.id)}
                  style={{ width: 16, height: 16, accentColor: "#4B2E83", marginTop: 1, flexShrink: 0 }}
                />
                <span style={{ minWidth: 0 }}>
                  <span style={{ fontSize: 12.5, fontWeight: 600, display: "block" }}>{p.label}</span>
                  <span style={{ fontSize: 11, color: "#A19DAF" }}>{p.hint}</span>
                </span>
              </label>
            ))}
          </div>

          {confirmRemove ? (
            <div
              style={{
                background: "#FDF0F0",
                border: "1px solid #E8B4B4",
                borderRadius: 8,
                padding: 10,
              }}
            >
              <div style={{ fontSize: 12, fontWeight: 700, color: "#8A2E2E", marginBottom: 8 }}>
                Remove {member.name}'s access?
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <button
                  onClick={() => setConfirmRemove(false)}
                  style={{
                    flex: 1,
                    background: "transparent",
                    border: "1px solid #E0DCE8",
                    borderRadius: 7,
                    padding: "7px 0",
                    fontSize: 12,
                    fontWeight: 700,
                    cursor: "pointer",
                    color: "#565064",
                  }}
                >
                  Cancel
                </button>
                <button
                  onClick={() => onRemove(member.id)}
                  style={{
                    flex: 1,
                    background: "#B33A3A",
                    border: "none",
                    borderRadius: 7,
                    padding: "7px 0",
                    fontSize: 12,
                    fontWeight: 700,
                    cursor: "pointer",
                    color: "#fff",
                  }}
                >
                  Yes, remove
                </button>
              </div>
            </div>
          ) : (
            <button
              onClick={() => setConfirmRemove(true)}
              style={{
                background: "transparent",
                border: "1px solid #E8B4B4",
                borderRadius: 7,
                padding: "7px 12px",
                fontSize: 11.5,
                fontWeight: 700,
                cursor: "pointer",
                color: "#8A2E2E",
              }}
            >
              Remove access
            </button>
          )}
        </div>
      )}
    </div>
  );
}

